import React, { useEffect, useState, useCallback } from 'react';
import {
  getProducts, getCategories, createProduct, updateProduct,
  deleteProduct, uploadProductFile,
} from './api';
import { useToast } from './Toast';

const EMPTY = {
  name:'', description:'', price:'', sale_price:'',
  stock:'', category_id:'', sizes:[], colors:[],
  ar_enabled: false,
};

export default function Products() {
  const [products, setProducts] = useState([]);
  const [total,    setTotal]    = useState(0);
  const [cats,     setCats]     = useState([]);
  const [page,     setPage]     = useState(1);
  const [search,   setSearch]   = useState('');
  const [loading,  setLoading]  = useState(true);
  const [modal,    setModal]    = useState(null); // null | 'create' | {product}
  const [delId,    setDelId]    = useState(null);
  const [form,     setForm]     = useState(EMPTY);
  const [saving,   setSaving]   = useState(false);
  const [uploadFile, setUploadFile] = useState(null);
  const toast = useToast();
  const PER = 12;

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await getProducts({ page, limit: PER, search: search || undefined });
      setProducts(r.products || []);
      setTotal(r.total || 0);
    } finally {
      setLoading(false);
    }
  }, [page, search]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    getCategories().then(r => setCats(r.categories || []));
  }, []);

  function openCreate() { setForm(EMPTY); setUploadFile(null); setModal('create'); }
  function openEdit(p) {
    setForm({
      name: p.name, description: p.description || '',
      price: p.price, sale_price: p.sale_price || '',
      stock: p.stock, category_id: p.category_id || '',
      sizes: p.sizes || [], colors: p.colors || [],
      ar_enabled: !!p.ar_enabled,
    });
    setUploadFile(null);
    setModal(p);
  }

  async function save() {
    if (!form.name || !form.price) return toast('Name and price required', 'error');
    setSaving(true);
    try {
      const payload = {
        ...form,
        price:      Number(form.price),
        sale_price: form.sale_price ? Number(form.sale_price) : null,
        stock:      Number(form.stock),
        category_id: form.category_id ? Number(form.category_id) : null,
      };
      if (modal === 'create') {
        const r = await createProduct(payload);
        toast('Product created', 'success');
        // Upload image if selected
        if (uploadFile && r.product_id) {
          await uploadProductFile(r.product_id, uploadFile);
        }
      } else {
        await updateProduct(modal.id, payload);
        if (uploadFile) await uploadProductFile(modal.id, uploadFile);
        toast('Product updated', 'success');
      }
      setModal(null);
      load();
    } catch (e) {
      toast(e.message, 'error');
    } finally {
      setSaving(false);
    }
  }

  async function remove(id) {
    try {
      await deleteProduct(id);
      toast('Product removed', 'success');
      setDelId(null);
      load();
    } catch (e) {
      toast(e.message, 'error');
    }
  }

  const pages = Math.ceil(total / PER);

  function toggleSize(s) {
    setForm(f => ({
      ...f,
      sizes: f.sizes.includes(s) ? f.sizes.filter(x => x !== s) : [...f.sizes, s],
    }));
  }

  const SIZES = ['XS','S','M','L','XL','XXL'];
  const COLORS = ['Black','White','Red','Blue','Green','Yellow','Pink','Gray','Navy','Beige'];

  function toggleColor(c) {
    setForm(f => ({
      ...f,
      colors: f.colors.includes(c) ? f.colors.filter(x => x !== c) : [...f.colors, c],
    }));
  }

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h1 style={styles.h1}>Products</h1>
          <p style={{ color:'var(--muted)', fontSize:13 }}>{total} items total</p>
        </div>
        <button className="btn btn-primary" onClick={openCreate}>
          <PlusIcon /> Add Product
        </button>
      </div>

      {/* Search */}
      <div style={{ marginBottom:20, maxWidth:340 }}>
        <input
          className="input" placeholder="Search products…"
          value={search}
          onChange={e => { setSearch(e.target.value); setPage(1); }}
        />
      </div>

      {/* Table */}
      <div className="card" style={{ padding:0 }}>
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Image</th>
                <th>Name</th>
                <th>Category</th>
                <th>Price</th>
                <th>Stock</th>
                <th>AR</th>
                <th style={{ textAlign:'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={7} style={{ textAlign:'center', padding:'40px 0' }}>
                  <span className="spinner" />
                </td></tr>
              ) : products.length === 0 ? (
                <tr><td colSpan={7}>
                  <div className="empty"><div className="empty-icon">📦</div><p>No products found</p></div>
                </td></tr>
              ) : products.map(p => (
                <tr key={p.id}>
                  <td>
                    <div style={styles.thumb}>
                      {p.images?.[0]
                        ? <img src={`http://localhost:5000${p.images[0]}`} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }} />
                        : <ImgPlaceholder />}
                    </div>
                  </td>
                  <td>
                    <div style={{ fontWeight:600 }}>{p.name}</div>
                    <div style={{ fontSize:11, color:'var(--muted)', marginTop:2 }}>/{p.slug}</div>
                  </td>
                  <td>
                    {p.category_name
                      ? <span className="badge badge-gray">{p.category_name}</span>
                      : <span style={{ color:'var(--muted)' }}>—</span>}
                  </td>
                  <td>
                    <div style={{ fontWeight:600 }}>${Number(p.price).toFixed(2)}</div>
                    {p.sale_price && (
                      <div style={{ fontSize:11, color:'var(--green)', marginTop:2 }}>
                        Sale: ${Number(p.sale_price).toFixed(2)}
                      </div>
                    )}
                  </td>
                  <td>
                    <span className={`badge badge-${p.stock > 10 ? 'green' : p.stock > 0 ? 'yellow' : 'red'}`}>
                      {p.stock}
                    </span>
                  </td>
                  <td>
                    {p.ar_enabled
                      ? <span className="badge badge-blue">AR</span>
                      : <span style={{ color:'var(--muted)', fontSize:11 }}>—</span>}
                  </td>
                  <td>
                    <div style={{ display:'flex', gap:6, justifyContent:'flex-end' }}>
                      <button className="btn btn-ghost btn-sm" onClick={() => openEdit(p)}>Edit</button>
                      <button className="btn btn-danger btn-sm" onClick={() => setDelId(p.id)}>Del</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {pages > 1 && (
          <div className="pagination" style={{ padding:'12px 16px' }}>
            {Array.from({ length: pages }, (_, i) => i + 1).map(n => (
              <button key={n} className={`page-btn${page===n?' active':''}`} onClick={() => setPage(n)}>{n}</button>
            ))}
          </div>
        )}
      </div>

      {/* Product Modal */}
      {modal !== null && (
        <div className="overlay" onClick={e => e.target === e.currentTarget && setModal(null)}>
          <div className="modal" style={{ maxWidth:580 }}>
            <h3>{modal === 'create' ? 'Add New Product' : 'Edit Product'}</h3>
            <div style={styles.grid2}>
              <div>
                <label className="label">Product Name *</label>
                <input className="input" value={form.name} onChange={e => setForm({...form, name:e.target.value})} placeholder="e.g. Silk Slip Dress" />
              </div>
              <div>
                <label className="label">Category</label>
                <select className="input" value={form.category_id} onChange={e => setForm({...form, category_id:e.target.value})}>
                  <option value="">No Category</option>
                  {cats.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div>
                <label className="label">Price *</label>
                <input className="input" type="number" step="0.01" value={form.price} onChange={e => setForm({...form, price:e.target.value})} placeholder="0.00" />
              </div>
              <div>
                <label className="label">Sale Price</label>
                <input className="input" type="number" step="0.01" value={form.sale_price} onChange={e => setForm({...form, sale_price:e.target.value})} placeholder="Optional" />
              </div>
              <div>
                <label className="label">Stock</label>
                <input className="input" type="number" value={form.stock} onChange={e => setForm({...form, stock:e.target.value})} placeholder="0" />
              </div>
              <div style={{ display:'flex', alignItems:'center', gap:10, paddingTop:18 }}>
                <input type="checkbox" id="ar" checked={form.ar_enabled} onChange={e => setForm({...form, ar_enabled:e.target.checked})} style={{ accentColor:'var(--accent)', width:15, height:15 }} />
                <label htmlFor="ar" style={{ fontSize:13, color:'var(--text)', cursor:'pointer' }}>AR Enabled</label>
              </div>
            </div>

            <div style={{ marginTop:14 }}>
              <label className="label">Description</label>
              <textarea className="input" rows={3} value={form.description} onChange={e => setForm({...form, description:e.target.value})} placeholder="Product description…" style={{ resize:'vertical' }} />
            </div>

            {/* Sizes */}
            <div style={{ marginTop:14 }}>
              <label className="label">Sizes</label>
              <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
                {SIZES.map(s => (
                  <button key={s} type="button"
                    onClick={() => toggleSize(s)}
                    style={{
                      padding:'5px 12px', borderRadius:7, fontSize:12, fontFamily:'var(--font)',
                      cursor:'pointer', border:'1px solid',
                      borderColor: form.sizes.includes(s) ? 'var(--accent)' : 'var(--border)',
                      background: form.sizes.includes(s) ? 'rgba(201,169,110,0.15)' : 'transparent',
                      color: form.sizes.includes(s) ? 'var(--accent)' : 'var(--muted)',
                      transition:'var(--transition)',
                    }}
                  >{s}</button>
                ))}
              </div>
            </div>

            {/* Colors */}
            <div style={{ marginTop:14 }}>
              <label className="label">Colors</label>
              <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
                {COLORS.map(c => (
                  <button key={c} type="button"
                    onClick={() => toggleColor(c)}
                    style={{
                      padding:'5px 12px', borderRadius:7, fontSize:12, fontFamily:'var(--font)',
                      cursor:'pointer', border:'1px solid',
                      borderColor: form.colors.includes(c) ? 'var(--accent)' : 'var(--border)',
                      background: form.colors.includes(c) ? 'rgba(201,169,110,0.15)' : 'transparent',
                      color: form.colors.includes(c) ? 'var(--accent)' : 'var(--muted)',
                      transition:'var(--transition)',
                    }}
                  >{c}</button>
                ))}
              </div>
            </div>

            {/* File upload */}
            <div style={{ marginTop:14 }}>
              <label className="label">Upload Image / 3D Model (.jpg .png .glb)</label>
              <input
                type="file"
                accept=".jpg,.jpeg,.png,.webp,.glb,.gltf"
                onChange={e => setUploadFile(e.target.files[0] || null)}
                style={{ ...styles.fileInput }}
              />
              {uploadFile && <p style={{ fontSize:11, color:'var(--green)', marginTop:6 }}>Selected: {uploadFile.name}</p>}
            </div>

            <div style={{ display:'flex', gap:10, marginTop:22, justifyContent:'flex-end' }}>
              <button className="btn btn-ghost" onClick={() => setModal(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={save} disabled={saving}>
                {saving ? <span className="spinner" style={{ width:14, height:14 }} /> : null}
                {saving ? 'Saving…' : modal === 'create' ? 'Create Product' : 'Save Changes'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirm */}
      {delId && (
        <div className="overlay" onClick={e => e.target === e.currentTarget && setDelId(null)}>
          <div className="modal" style={{ maxWidth:360, textAlign:'center' }}>
            <div style={{ fontSize:36, marginBottom:12 }}>🗑️</div>
            <h3 style={{ marginBottom:8 }}>Remove Product?</h3>
            <p style={{ color:'var(--muted)', fontSize:13, marginBottom:24 }}>This will hide the product from your store. This action can be reversed.</p>
            <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
              <button className="btn btn-ghost" onClick={() => setDelId(null)}>Cancel</button>
              <button className="btn btn-danger" onClick={() => remove(delId)}>Remove</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

